// Faithful subset of `schedule.Job` (the pure-Python `schedule` package).
//
// Only the slice the program touches is modelled: constructing a job through
// `Scheduler.every()` and reading a unit property (`.minutes`). Job execution
// (`.do()`, `.run()`, `.at()`, weekday helpers) is deliberately absent, so this
// module creates no timers and never keeps the event loop alive.

// The library's exception hierarchy (schedule/__init__.py):
//   ScheduleError -> ScheduleValueError -> IntervalError
// They live here because `Job` is the only thing in this subset that raises them.

/** Base class for all schedule errors. */
export class ScheduleError extends Error {}

/** Base class for schedule value errors. */
export class ScheduleValueError extends ScheduleError {}

/** An improper interval was used (e.g. `.minute` with an interval other than 1). */
export class IntervalError extends ScheduleValueError {}

/**
 * Can be returned from a job function to unschedule that job.
 * A sentinel class, exactly as the library exposes it (never instantiated).
 */
export class CancelJob {}

/**
 * `interval === 1` in the Python sense, tolerating BigInt intervals.
 * Python's `self.interval != 1` compares numerically across int types; our
 * intervals may be BigInt (arbitrary-precision ints), so 1n counts as 1 too.
 * A deliberate `===` per type avoids JS loose-equality coercing e.g. '1'.
 */
function isIntervalOne(interval) {
  return typeof interval === 'bigint' ? interval === 1n : interval === 1;
}

/**
 * A periodic job as returned by `Scheduler.every()`.
 *
 * The interval is stored verbatim with no validation — 0, negatives and
 * arbitrary-precision BigInt values all pass through untouched, mirroring
 * `Job.__init__` which merely assigns `self.interval = interval`.
 */
export class Job {
  constructor(interval, scheduler = null) {
    this.interval = interval; // pause interval * unit between runs
    this.latest = null; // upper limit to the interval
    this.jobFunc = null; // the job job_func to run
    this.unit = null; // time unit, e.g. 'minutes' — unset until a unit property is read
    this.atTime = null; // optional time at which this job runs
    this.lastRun = null; // datetime of the last run
    this.nextRun = null; // datetime of the next run
    this.period = null; // timedelta between runs, only valid for
    this.startDay = null; // specific day of the week to start on
    this.cancelAfter = null; // datetime after which to cancel the job
    this.tags = new Set(); // unique set of tags for the job
    this.scheduler = scheduler; // scheduler to register with once `.do()` is called
  }

  // --- plural units: set the unit and return the job for chaining ---

  get seconds() {
    this.unit = 'seconds';
    return this;
  }

  get minutes() {
    this.unit = 'minutes';
    return this;
  }

  get hours() {
    this.unit = 'hours';
    return this;
  }

  get days() {
    this.unit = 'days';
    return this;
  }

  get weeks() {
    this.unit = 'weeks';
    return this;
  }

  // --- singular units: only legal for an interval of 1 ---
  // Mirrors the library's guard `if self.interval != 1: raise IntervalError(...)`,
  // then delegates to the plural property.

  get second() {
    if (!isIntervalOne(this.interval)) {
      throw new IntervalError('Use seconds instead of second');
    }
    return this.seconds;
  }

  get minute() {
    if (!isIntervalOne(this.interval)) {
      throw new IntervalError('Use minutes instead of minute');
    }
    return this.minutes;
  }

  get hour() {
    if (!isIntervalOne(this.interval)) {
      throw new IntervalError('Use hours instead of hour');
    }
    return this.hours;
  }

  get day() {
    if (!isIntervalOne(this.interval)) {
      throw new IntervalError('Use days instead of day');
    }
    return this.days;
  }

  get week() {
    if (!isIntervalOne(this.interval)) {
      throw new IntervalError('Use weeks instead of week');
    }
    return this.weeks;
  }
}

// Faithful subset of `schedule.Scheduler`.

import { Job } from './job.mjs';

/**
 * Objects instantiated by `Scheduler` are factories to create jobs, keep
 * record of scheduled jobs and handle their execution.
 *
 * Only job *creation* is modelled here. As in the library, `every()` builds the
 * job but does not append it to `self.jobs` — registration happens inside
 * `Job.do()`, which is out of scope. Consequently nothing here starts a timer.
 */
export class Scheduler {
  constructor() {
    this.jobs = []; // scheduled jobs, populated when a job's `.do()` is called
  }

  /**
   * Schedule a new periodic job.
   * @param {number|bigint} interval a quantity of a certain time unit
   * @returns {Job} an unconfigured `Job`
   */
  every(interval = 1) {
    return new Job(interval, this);
  }
}

// Public surface of the `schedule` subset, mirroring `schedule/__init__.py`:
// a module-level default scheduler plus the `every()` convenience function.

import { Job } from './job.mjs';
import { Scheduler } from './scheduler.mjs';

export {
  Job,
  ScheduleError,
  ScheduleValueError,
  IntervalError,
  CancelJob,
} from './job.mjs';
export { Scheduler } from './scheduler.mjs';

/** Default scheduler instance (`schedule.default_scheduler`). */
export const defaultScheduler = new Scheduler();

/**
 * Calls `every` on the default scheduler; the returned job is not registered
 * anywhere until `.do()` is called, so this has no side effects.
 * @param {number|bigint} interval
 * @returns {Job}
 */
export function every(interval = 1) {
  return defaultScheduler.every(interval);
}

