cd /output && node --input-type=module -e "
import * as schedule from '/output/lib/schedule/index.mjs';
const cases = [0, 1, -3, 5, 99999999999999999999n, 9007199254740993n, -99999999999999999999n];
for (const v of cases) {
  const job = schedule.every(v).minutes;
  console.log(String(job.interval), '| unit=' + job.unit, '| jobs=' + schedule.defaultScheduler.jobs.length);
}
// unit is null before any unit property is read
const j = schedule.every(2);
console.log('initial unit:', j.unit, '| tags:', j.tags instanceof Set, '| fields:', Object.keys(j).join(','));
// singular guards
try { schedule.every(2).minute; } catch (e) { console.log(e.constructor.name + ':', e.message, '| isScheduleValueError=', e instanceof schedule.ScheduleValueError, e instanceof schedule.ScheduleError, e instanceof Error); }
console.log('1n.minute ->', schedule.every(1n).minute.unit, '| 1.week ->', schedule.every(1).week.unit);
for (const p of ['second','hour','day','week']) { try { schedule.every(0)[p]; } catch (e) { console.log(p, '=>', e.message); } }
console.log('every() default:', schedule.every().interval, '| CancelJob:', typeof schedule.CancelJob, schedule.CancelJob.name);
console.log('Job/Scheduler exports:', schedule.Job.name, schedule.Scheduler.name, new schedule.Scheduler().jobs.length);
"

